[{"order":1,"type":"heading","text":"Zero-Downtime Deployments and Envoy in Laravel"},{"order":2,"type":"paragraph","text":"Achieving zero-downtime deployments is crucial for modern web applications. It ensures that your users experience no service interruptions or broken assets while you push new updates to production. In the Laravel ecosystem, Laravel Envoy provides an elegant, SSH-task runner written in PHP that makes orchestrating these complex deployments remarkably straightforward."},{"order":3,"type":"subheading","text":"Prerequisites and Architecture"},{"order":4,"type":"paragraph","text":"Before diving into Envoy, your production server should utilize a symlink-based deployment strategy. This means maintaining a releases directory where each deployment gets its own folder, and a current symlink pointing to the active release. This structure allows us to instantly switch between versions and rollback just as fast if something goes wrong."},{"order":5,"type":"bullet_point","text":"Install Laravel Envoy globally using Composer: composer global require laravel/envoy."},{"order":6,"type":"bullet_point","text":"Ensure SSH key-based authentication is configured between your deployment machine and the target server."},{"order":7,"type":"bullet_point","text":"Structure your remote server with /var/www/your-app/releases and /var/www/your-app/storage directories."},{"order":8,"type":"subheading","text":"Writing the Envoyfile.blade.php"},{"order":9,"type":"paragraph","text":"Laravel Envoy uses Blade syntax to define deployment tasks. Create an Envoyfile.blade.php in the root of your Laravel project. Below is a complete configuration for a zero-downtime deployment."},{"order":10,"type":"code","text":"@servers(['web' => 'user@your-production-server.com'])

@setup
    $repository = 'git@github.com:your-username/your-repo.git';
    $releases_dir = '/var/www/your-app/releases';
    $app_dir = '/var/www/your-app';
    $release = 'release-' . date('YmdHis');
    $new_release_dir = $releases_dir . '/' . $release;
@endsetup

@story('deploy')
    clone_repository
    run_composer
    update_symlinks
    optimize_app
    clean_old_releases
@endstory

@task('clone_repository')
    echo 'Cloning repository...'
    git clone --depth 1 {{ $repository }} {{ $new_release_dir }}
@endtask

@task('run_composer')
    echo 'Running Composer...'
    cd {{ $new_release_dir }}
    composer install --no-dev --prefer-dist --no-interaction --optimize-autoloader
@endtask

@task('update_symlinks')
    echo 'Linking storage directory...'
    rm -rf {{ $new_release_dir }}/storage
    ln -nfs {{ $app_dir }}/storage {{ $new_release_dir }}/storage

    echo 'Linking .env file...'
    ln -nfs {{ $app_dir }}/.env {{ $new_release_dir }}/.env

    echo 'Updating current symlink...'
    ln -nfs {{ $new_release_dir }} {{ $app_dir }}/current
@endtask

@task('optimize_app')
    echo 'Optimizing application...'
    cd {{ $app_dir }}/current
    php artisan config:cache
    php artisan route:cache
    php artisan view:cache
    php artisan migrate --force
@endtask

@task('clean_old_releases')
    echo 'Cleaning up old releases...'
    cd {{ $releases_dir }}
    ls -t | tail -n +6 | xargs rm -rf
@endtask"},{"order":11,"type":"subheading","text":"Executing the Deployment"},{"order":12,"type":"paragraph","text":"With your Envoyfile properly configured, running the deployment is as simple as executing a single command in your local terminal. Envoy will connect to your remote server via SSH and execute the defined tasks sequentially."},{"order":13,"type":"code","text":"envoy run deploy"},{"order":14,"type":"subheading","text":"Handling Queue Workers and Caches"},{"order":15,"type":"paragraph","text":"In a zero-downtime deployment, you must also gracefully restart your queue workers so they pick up the new code changes without dropping active jobs. Add a restart_workers task to your Envoy story to handle this using Laravel Horizon or standard queue restart commands."},{"order":16,"type":"code","text":"@task('restart_workers')
    echo 'Restarting queue workers...'
    cd {{ $app_dir }}/current
    php artisan queue:restart
    # If using Horizon:
    php artisan horizon:terminate
@endtask"},{"order":17,"type":"paragraph","text":"By integrating these steps into your Laravel Envoy workflow, you ensure a bulletproof deployment pipeline that keeps your application fast, secure, and always online for your users."}]
